// BlockSoundGroup returns registered events by block, or zero for an invalid block.
func BlockSoundGroup(b Block) SoundGroup {
	if b >= BlockCount {
		return SoundGroup{}
	}
	return soundTypes[blockSoundTypes[b]].SoundGroup
}

