// BlockSoundType returns the SoundType of a block; the zero SoundType for a
// Block past BlockCount.
func BlockSoundType(b Block) SoundType {
	if b >= BlockCount {
		return SoundType{}
	}
	return soundTypes[blockSoundTypes[b]]
}
